 public List<JsonNode> shipmentFacts(long org,long lot){return shipmentMapper.selectList(new QueryWrapper<FinishedShipmentEntity>().eq("org_id",org).eq("material_lot_id",lot).orderByAsc("id")).stream().map(x->(JsonNode)stable(view(x))).toList();}
